def _group_lock(path):
    """Take the exclusive group-commit lock; returns fd or None."""
    if fcntl is None:
        return None
    lock_path = path + _GROUP_LOCK_SUFFIX
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o666)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
    except OSError:
        os.close(fd)
        raise
    return fd
```
