# Group-cursor state.  ``path.groupcursor`` is the unified commit record
# of a group checkpoint: one atomically published JSON plan covering the
# whole group.  ``path.groupcursor.lock`` anchors the inter-process lock
# that serialises group commits; it is never renamed, so the lock stays
# valid for the whole commit.  ``path.groupcursor.tmp`` is the staging
# name of the next commit record.
_GROUP_COMMIT_SUFFIX = ".groupcursor"
_GROUP_LOCK_SUFFIX = ".groupcursor.lock"
_GROUP_COMMIT_TMP_SUFFIX = ".groupcursor.tmp"
```

