def _group_pairs(rest):
    """Parse CURSOR POSITION pairs tolerating the argument order.

    Accepts alternating ``CURSOR POSITION`` pairs, alternating
    ``POSITION CURSOR`` pairs, or all cursor files followed by all
    positions; positions are the arguments that parse as integers.
    """
    def _is_int(text):
        try:
            int(text)
        except ValueError:
            return False
        return True

    if not rest or len(rest) % 2 != 0:
        return None
    if all(not _is_int(rest[i]) and _is_int(rest[i + 1])
           for i in range(0, len(rest), 2)):
        return [(rest[i], int(rest[i + 1])) for i in range(0, len(rest), 2)]
    if all(_is_int(rest[i]) and not _is_int(rest[i + 1])
           for i in range(0, len(rest), 2)):
        return [(rest[i + 1], int(rest[i])) for i in range(0, len(rest), 2)]
    half = len(rest) // 2
    cursors, numbers = rest[:half], rest[half:]
    if all(not _is_int(text) for text in cursors) and all(
        _is_int(text) for text in numbers
    ):
        return list(zip(cursors, [int(text) for text in numbers]))
    return None
